files.content:
terraform {
  required_version = ">= 1.5.0, < 2.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.63.0, < 7.0.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = local.tags
  }
}

variable "aws_region" {
  type        = string
  description = "AWS Region selected by the immutable Architecture Document."
  default     = "us-east-1"
}

variable "event_sqs_consumer_dlq_artifact_path" {
  type        = string
  description = "Stable relative package output produced by the separate Prompt 32A workload builder."
  default     = "../application/artifacts/workload_event_sqs_consumer_dlq/function.zip"
  validation {
    condition     = can(regex("^\\.\\.?/", var.event_sqs_consumer_dlq_artifact_path))
    error_message = "Package path must be repository-relative and begin with ./ or ../; absolute machine paths are forbidden."
  }
}

variable "stage" {
  type        = string
  description = "Architecture variable stage."
  default     = "test"
}

locals {
  tags = {
    CloudMarkupArchitecture     = "architecture_event_sqs_consumer_dlq"
    CloudMarkupRevision         = "revision_event_sqs_consumer_dlq_1"
    CloudMarkupSolutionRevision = "solution_notes_revision_1"
    ManagedBy                   = "CloudMarkup"
  }
}

resource "aws_lambda_function" "event_sqs_consumer_dlq" {
  function_name                  = "event_sqs_consumer_dlq"
  description                    = "CloudMarkup notes-API workload."
  role                           = aws_iam_role.event_sqs_consumer_dlq_role.arn
  handler                        = "index.handler"
  runtime                        = "nodejs24.x"
  architectures                  = ["arm64"]
  memory_size                    = 256
  reserved_concurrent_executions = 10
  timeout                        = 30
  filename                       = var.event_sqs_consumer_dlq_artifact_path
  source_code_hash               = filebase64sha256(var.event_sqs_consumer_dlq_artifact_path)
  tracing_config {
    mode = "Active"
  }
  environment {
    variables = {
      "APP_STAGE" = var.stage
    }
  }
  tags = local.tags
}

data "aws_iam_policy_document" "event_logs_policy_sqs_consumer_dlq" {
  statement {
    sid       = "eventlogspolicysqsconsumerdlq"
    effect    = "Allow"
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    resources = [format("%s:*", aws_cloudwatch_log_group.event_logs_sqs_consumer_dlq.arn)]
  }
}

data "aws_iam_policy_document" "queue_consumer_policy" {
  statement {
    sid       = "queueconsumerpolicy"
    effect    = "Allow"
    actions   = ["sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ReceiveMessage"]
    resources = [aws_sqs_queue.event_sqs_consumer_dlq_queue.arn]
  }
}

data "aws_iam_policy_document" "trust_policy" {
  statement {
    sid     = "trustpolicy"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "event_logs_policy_sqs_consumer_dlq" {
  name   = "event_logs_policy_sqs_consumer_dlq"
  role   = aws_iam_role.event_sqs_consumer_dlq_role.name
  policy = data.aws_iam_policy_document.event_logs_policy_sqs_consumer_dlq.json
}

resource "aws_iam_role_policy" "queue_consumer_policy" {
  name   = "queue_consumer_policy"
  role   = aws_iam_role.event_sqs_consumer_dlq_role.name
  policy = data.aws_iam_policy_document.queue_consumer_policy.json
}

resource "aws_sqs_queue" "event_sqs_consumer_dlq_dead_letter" {
  name                        = "image-processing-dlq"
  fifo_queue                  = false
  content_based_deduplication = false
  sqs_managed_sse_enabled     = true
  message_retention_seconds   = 345600
  receive_wait_time_seconds   = 20
  visibility_timeout_seconds  = 60
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}

resource "aws_sqs_queue" "event_sqs_consumer_dlq_queue" {
  name                        = "image-processing"
  fifo_queue                  = false
  content_based_deduplication = false
  sqs_managed_sse_enabled     = true
  message_retention_seconds   = 345600
  receive_wait_time_seconds   = 20
  visibility_timeout_seconds  = 60
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.event_sqs_consumer_dlq_dead_letter.arn
    maxReceiveCount     = 5
  })
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}

resource "aws_sqs_queue_redrive_allow_policy" "event_sqs_consumer_dlq_dead_letter_d4abbcee34" {
  queue_url = aws_sqs_queue.event_sqs_consumer_dlq_dead_letter.id
  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.event_sqs_consumer_dlq_queue.arn]
  })
}

resource "aws_lambda_event_source_mapping" "event_sqs_consumer_dlq_queue_c96b502da4" {
  event_source_arn                   = aws_sqs_queue.event_sqs_consumer_dlq_queue.arn
  function_name                      = aws_lambda_function.event_sqs_consumer_dlq.arn
  batch_size                         = 10
  maximum_batching_window_in_seconds = 5
  function_response_types            = ["ReportBatchItemFailures"]
  scaling_config {
    maximum_concurrency = 10
  }
}

resource "aws_cloudwatch_log_group" "event_logs_sqs_consumer_dlq" {
  name              = "/aws/lambda/event_sqs_consumer_dlq"
  log_group_class   = "STANDARD"
  retention_in_days = 30
  lifecycle {
    prevent_destroy = true
  }
  tags = local.tags
}
